function*l(c={}){const e=Object.entries(c);if(e.length===0)return;const t=[{index:e.length-1,partial:{}}];for(;t.length>0;){const s=t.pop();if(!s)break;const{index:n,partial:a}=s;if(n<0){yield a;continue}const[o,r]=e[n];for(let i=r.length-1;i>=0;i--)t.push({index:n-1,partial:Object.assign(Object.assign({},a),{[o]:r[i]})})}}export{l as cartesianProductGenerator};
